import java.util.*;

class Solution {
    public boolean isValid(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        Map<Character, Character> pairs = new HashMap<>();
        pairs.put(')', '(');
        pairs.put(']', '[');
        pairs.put('}', '{');

        for (char c : s.toCharArray()) {
            if (pairs.containsKey(c)) {
                if (stack.isEmpty() || stack.pop() != pairs.get(c)) {
                    return false;
                }
            } else {
                stack.push(c);
            }
        }

        return stack.isEmpty();
    }
}

import java.util.*;

class Solution {
    public boolean isValid(String s) {
        Deque<Character> stack = new ArrayDeque<>();

        for (char c : s.toCharArray()) {
            if (c == '(') {
                stack.push(')');
            } else if (c == '[') {
                stack.push(']');
            } else if (c == '{') {
                stack.push('}');
            } else if (stack.isEmpty() || stack.pop() != c) {
                return false;
            }
        }

        return stack.isEmpty();
    }
}

class Solution {
    public boolean isValid(String s) {
        char[] stack = new char[s.length()];
        int top = -1;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(' || c == '[' || c == '{') {
                stack[++top] = c;
            } else {
                if (top < 0) {
                    return false;
                }
                char open = stack[top--];
                if ((c == ')' && open != '(') ||
                    (c == ']' && open != '[') ||
                    (c == '}' && open != '{')) {
                    return false;
                }
            }
        }

        return top == -1;
    }
}

class Solution {
    private String s;
    private int index;

    public boolean isValid(String s) {
        this.s = s;
        this.index = 0;
        return parseUntil('\0') && index == s.length();
    }

    private boolean parseUntil(char expected) {
        while (index < s.length()) {
            char c = s.charAt(index);
            if (c == ')' || c == ']' || c == '}') {
                if (expected != '\0' && c == expected) {
                    index++;
                    return true;
                }
                return false;
            }

            char close = matchingClose(c);
            if (close == '\0') {
                return false;
            }
            index++;
            if (!parseUntil(close)) {
                return false;
            }
        }

        return expected == '\0';
    }

    private char matchingClose(char c) {
        if (c == '(') {
            return ')';
        }
        if (c == '[') {
            return ']';
        }
        if (c == '{') {
            return '}';
        }
        return '\0';
    }
}

class Solution {
    public boolean isValid(String s) {
        int previousLength;
        do {
            previousLength = s.length();
            s = s.replace("()", "").replace("[]", "").replace("{}", "");
        } while (s.length() != previousLength);

        return s.isEmpty();
    }
}
